            newSellTaxes.marketing,
            newSellTaxes.liquidity,
            newSellTaxes.dev,
            newSellTaxes.buyback
        );

        // Compare initial and new values
        bool buyTaxesChanged = (
            newBuyTaxes.rfi != initialBuyTaxes.rfi ||
            newBuyTaxes.marketing != initialBuyTaxes.marketing ||
            newBuyTaxes.liquidity != initialBuyTaxes.liquidity ||
            newBuyTaxes.dev != initialBuyTaxes.dev ||
            newBuyTaxes.buyback != initialBuyTaxes.buyback
        );

        bool sellTaxesChanged = (
