            newSellTaxes.marketing != initialSellTaxes.marketing ||
            newSellTaxes.liquidity != initialSellTaxes.liquidity ||
            newSellTaxes.dev != initialSellTaxes.dev ||
            newSellTaxes.buyback != initialSellTaxes.buyback
        );

        console2.log("--- Verification ---");
        console2.log("Buy taxes changed: %s", buyTaxesChanged ? "true" : "false");
        console2.log("Sell taxes changed: %s", sellTaxesChanged ? "true" : "false");

